// BUG FIX: `new Date().toISOString().slice(0, 10)` was used all over the
// app (invoices, quotes, purchases, expenses, deliveries, and the
// accounting/reports date-range math) to get "today" or a date boundary
// as YYYY-MM-DD. toISOString() always converts to UTC first — so for
// anyone in a timezone AHEAD of UTC (which is most of this app's target
// market: Lagos/Accra are UTC+0 so unaffected, but Nairobi, Kampala,
// Dar es Salaam, Cairo, Dubai and the rest of East/Central Africa and the
// Middle East are UTC+1 to UTC+4), the UTC date can be a full day behind
// the user's actual local date for part of every day (midnight to
// UTC+offset each morning). A merchant opening shop at 7am in Nairobi
// (UTC+3) creating a new purchase order would silently get YESTERDAY's
// date pre-filled. localDateStr() reads the local Y/M/D components
// instead, so it always matches the date on the user's own wall clock.
export function localDateStr(date: Date = new Date()): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

export function formatMoney(amount: number, currency: string): string {
  const info = CURRENCIES[currency] ?? { symbol: currency, decimals: 2 };
  const value = Number(amount || 0);
  const sign = value < 0 ? '-' : '';
  const abs = Math.abs(value);
  const fixed = abs.toFixed(info.decimals);
  const [intPart, decPart] = fixed.split('.');
  // Manual ASCII-only grouping — avoids the Unicode narrow-no-break-space
  // that Intl/toLocaleString('fr-FR') uses, which isn't in jsPDF's default
  // font glyph set and was rendering as a stray "/" on printed invoices.
  const grouped = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  const formatted = decPart ? `${grouped},${decPart}` : grouped;
  return `${sign}${formatted} ${info.symbol}`;
}

export function getCountry(code: string): CountryInfo | undefined {
  return COUNTRIES.find((c) => c.code === code);
}

export const CONTINENT_LABELS: Record<CountryInfo['continent'], string> = {
  Africa: 'Afrique',
  Asia: 'Asie',
  'Middle East': 'Moyen-Orient',
  Europe: 'Europe',
  'North America': 'Amérique du Nord',
  'Central America & Caribbean': 'Amérique centrale & Caraïbes',
  'South America': 'Amérique du Sud',
  Oceania: 'Océanie',
};

// Groups all countries by continent, in a stable display order (Africa
// first, since it's the product's historical/primary market), each group
// sorted alphabetically by name. Replaces the old hardcoded
// `!['AE','US','FR','GB'].includes(code)` split, which silently lumped
// every non-African country into a single "international" bucket and broke
// down as soon as more than those 4 extra countries existed.
export function groupCountriesByContinent(): { continent: CountryInfo['continent']; label: string; countries: CountryInfo[] }[] {
  const order: CountryInfo['continent'][] = [
    'Africa', 'Europe', 'Middle East', 'Asia', 'North America',
    'Central America & Caribbean', 'South America', 'Oceania',
  ];
  return order
    .map((continent) => ({
      continent,
      label: CONTINENT_LABELS[continent],
      countries: COUNTRIES.filter((c) => c.continent === continent).sort((a, b) => a.name.localeCompare(b.name)),
    }))
    .filter((g) => g.countries.length > 0);
}

export function convertToUSD(amount: number, currency: string): number {
  const rate = USD_REFERENCE_RATES[currency] ?? 1;
  return amount * rate;
}
